import { spawn } from "node:child_process";
import { mkdtemp, rm } from "node:fs/promises";
import { connect as connectSocket, createServer } from "node:net";
import os from "node:os";
import path from "node:path";

const root = process.cwd();
const temporary = await mkdtemp(path.join(os.tmpdir(), "ji-stage4-host-restart-"));
const database = path.join(temporary, "host.db");
try {
  await phase("write");
  await phase("read");
  process.stdout.write("STAGE4_HOST_RESTART_NO_DUPLICATES_OK\n");
} finally {
  await rm(temporary, { recursive: true, force: true });
}

async function phase(mode) {
  const gradle = process.platform === "win32" ? "cmd.exe" : `${root}/gradlew`;
  const gradleArgs = process.platform === "win32"
    ? ["/d", "/s", "/c", ".\\gradlew.bat", ":ji-host-web:runStage4RestartHostFixture", "--offline", "--no-daemon", `-PjiStage4RestartMode=${mode}`, `-PjiStage4RestartDatabase=${database}`]
    : [":ji-host-web:runStage4RestartHostFixture", "--offline", "--no-daemon", `-PjiStage4RestartMode=${mode}`, `-PjiStage4RestartDatabase=${database}`];
  const host = spawn(gradle, gradleArgs, { cwd: root, stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
  let output = "";
  let errors = "";
  host.stdout.setEncoding("utf8");
  host.stderr.setEncoding("utf8");
  host.stdout.on("data", value => { output += value; });
  host.stderr.on("data", value => { errors += value; });
  const state = await waitForReady(host, () => output, () => errors);
  const control = await connect(state.controlPort);
  try {
    control.write("ISSUE_TOKEN\n", "ascii");
    const token = [REDACTED_CREDENTIAL] readFrame(control);
    const tokenRelay = await oneUseTokenRelay(token);
    const storage = await authenticate(state.origin, tokenRelay.port);
    token.fill(0);
    await tokenRelay.closed;
    const storageRelay = await framedRelay(storage);
    storage.fill(0);
    try {
      await playwright(state.origin, storageRelay.port, mode);
      await storageRelay.used;
    } finally {
      storageRelay.close();
    }
    control.write("STOP\n", "ascii");
    control.end();
    const exit = await processExit(host, 30_000);
    if (exit !== 0) throw new Error(`restart Host ${mode} failed (${exit}); stderr bytes=${errors.length}`);
  } finally {
    control.destroy();
    if (running(host)) { host.kill(); await processExit(host, 10_000).catch(() => {}); }
  }
}

function waitForReady(child, stdout, stderr) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("restart Host readiness timed out")), 30_000);
    const inspect = () => {
      const match = stdout().match(/STAGE4_RESTART_HOST_READY (http:\/\/127\.0\.0\.1:\d+) CONTROL (\d+)/);
      if (match) { clearTimeout(timer); resolve({ origin: match[1], controlPort: Number(match[2]) }); }
    };
    child.stdout.on("data", inspect);
    child.once("exit", code => { clearTimeout(timer); reject(new Error(`restart Host exited (${code}); stderr bytes=${stderr().length}`)); });
  });
}

async function playwright(origin, sessionPort, mode) {
  const command = process.platform === "win32" ? "cmd.exe" : "corepack";
  const args = process.platform === "win32"
    ? ["/d", "/s", "/c", "corepack", "pnpm", "--offline", "--filter", "@ji/web-app", "exec", "playwright", "test", "--config", "playwright.real-host.config.ts", "e2e-real/stage4-host-restart.spec.ts"]
    : ["pnpm", "--offline", "--filter", "@ji/web-app", "exec", "playwright", "test", "--config", "playwright.real-host.config.ts", "e2e-real/stage4-host-restart.spec.ts"];
  const child = spawn(command, args, { cwd: root, stdio: "inherit", windowsHide: true, env: {
    ...process.env, JI_STAGE1_BASE_URL: origin, JI_STAGE1_SESSION_PORT: String(sessionPort), JI_STAGE4_RESTART_MODE: mode,
  }});
  const exit = await processExit(child, 60_000);
  if (exit !== 0) throw new Error(`restart Playwright ${mode} failed: ${exit}`);
}

async function authenticate(origin, tokenPort) {
  const child = spawn(process.execPath, [path.join(root, "scripts", "real-host-auth-bootstrap.mjs")], {
    cwd: root, stdio: ["ignore", "pipe", "pipe"], windowsHide: true,
    env: { ...process.env, JI_STAGE1_TOKEN_PORT: String(tokenPort), JI_STAGE1_BASE_URL: origin },
  });
  const frame = await readFrame(child.stdout);
  const exit = await processExit(child, 30_000);
  if (exit !== 0) { frame.fill(0); throw new Error("restart authentication bootstrap failed"); }
  return frame;
}

function connect(port) { return new Promise((resolve, reject) => { const socket = connectSocket({ host: "127.0.0.1", port }); socket.once("connect", () => resolve(socket)); socket.once("error", reject); }); }
function framedRelay(value) { return relay(value, false); }
function oneUseTokenRelay(value) { return relay(value, true); }
function relay(value, closeAfterUse) { return new Promise((resolve, reject) => { let usedResolve; const used = new Promise(done => { usedResolve = done; }); const secret = Buffer.from(value); const server = createServer({ pauseOnConnect: true }, socket => { const bytes = Buffer.from(secret); const header = Buffer.alloc(4); header.writeUInt32BE(bytes.length); socket.once("close", usedResolve); socket.end(Buffer.concat([header, bytes])); socket.resume(); bytes.fill(0); header.fill(0); if (closeAfterUse) server.close(); }); server.once("error", reject); server.listen({ host: "127.0.0.1", port: 0 }, () => resolve({ server, port: server.address().port, closed: used, used, close: () => { secret.fill(0); usedResolve(); server.close(); } })); }); }
function readFrame(socket) { let buffer = Buffer.alloc(0); return new Promise((resolve, reject) => { const data = chunk => { buffer = Buffer.concat([buffer, chunk]); if (buffer.length < 4) return; const length = buffer.readUInt32BE(0); if (length < 2 || length > 16_384) { cleanup(); reject(new Error("invalid frame")); return; } if (buffer.length < 4 + length) return; const value = Buffer.from(buffer.subarray(4, 4 + length)); cleanup(); buffer.fill(0); resolve(value); }; const error = reason => { cleanup(); reject(reason); }; const cleanup = () => { socket.off("data", data); socket.off("error", error); }; socket.on("data", data); socket.once("error", error); }); }
function running(child) { return child.exitCode === null && child.signalCode === null; }
function processExit(child, timeout = 120_000) { if (!running(child)) return Promise.resolve(child.exitCode ?? 1); return new Promise((resolve, reject) => { const timer = setTimeout(() => reject(new Error("process exit timed out")), timeout); child.once("exit", code => { clearTimeout(timer); resolve(code ?? 1); }); child.once("error", error => { clearTimeout(timer); reject(error); }); }); }
